begin;
create table if not exists public.housing_preferences (
 id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade,
 city text not null default 'Ahmedabad' check (city = 'Ahmedabad'), areas jsonb not null default '[]' check (jsonb_typeof(areas) = 'array'), min_rent integer check (min_rent between 0 and 1000000), max_rent integer check (max_rent between 0 and 1000000), bedrooms integer check (bedrooms between 0 and 10), property_types jsonb not null default '[]' check (jsonb_typeof(property_types) = 'array'), furnished text not null default 'any' check (furnished in ('any','furnished','semi_furnished','unfurnished')), move_in_date date, needs jsonb not null default '[]' check (jsonb_typeof(needs) = 'array'), consent_to_broker_contact boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (max_rent is null or min_rent is null or max_rent >= min_rent)
);
create table if not exists public.housing_listings (
 id uuid primary key default gen_random_uuid(), city text not null check (city = 'Ahmedabad'), area text, title text not null, description text not null default '', rent integer check (rent is null or rent between 0 and 1000000), bedrooms integer check (bedrooms is null or bedrooms between 0 and 10), property_type text, furnished text, amenities jsonb not null default '[]' check (jsonb_typeof(amenities) = 'array'), source_url text not null, source_name text not null, source_only boolean not null default true, last_seen_at timestamptz not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(source_url)
);
create table if not exists public.housing_match_runs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, preference_id uuid not null references public.housing_preferences(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.housing_match_results (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.housing_match_runs(id) on delete cascade, listing_id uuid not null references public.housing_listings(id) on delete cascade, score integer not null check (score between 0 and 100), reasons jsonb not null default '[]' check (jsonb_typeof(reasons) = 'array'), labels jsonb not null default '[]' check (jsonb_typeof(labels) = 'array'), unique(run_id, listing_id));
create table if not exists public.saved_housing_listings (user_id uuid not null references public.profiles(id) on delete cascade, listing_id uuid not null references public.housing_listings(id) on delete cascade, status text not null default 'saved' check (status in ('saved','dismissed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key(user_id, listing_id));
create table if not exists public.broker_profiles (id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, areas jsonb not null default '[]' check (jsonb_typeof(areas) = 'array'), verified boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.broker_match_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, broker_id uuid not null references public.broker_profiles(id) on delete restrict, listing_id uuid references public.housing_listings(id) on delete set null, message text not null check (char_length(message) between 1 and 2000), consent boolean not null check (consent = true), status text not null default 'pending' check (status in ('pending','sent','closed')), created_at timestamptz not null default now());
create table if not exists public.housing_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, event_type text not null, listing_id uuid references public.housing_listings(id) on delete set null, metadata jsonb not null default '{}' check (jsonb_typeof(metadata) = 'object'), created_at timestamptz not null default now());
create index if not exists housing_listings_city_seen on public.housing_listings(city,last_seen_at desc); create index if not exists housing_runs_user on public.housing_match_runs(user_id,created_at desc);
alter table public.housing_preferences enable row level security; alter table public.housing_listings enable row level security; alter table public.housing_match_runs enable row level security; alter table public.housing_match_results enable row level security; alter table public.saved_housing_listings enable row level security; alter table public.broker_profiles enable row level security; alter table public.broker_match_requests enable row level security; alter table public.housing_events enable row level security;
create policy housing_preferences_own on public.housing_preferences for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy housing_listings_read on public.housing_listings for select to authenticated using (true);
create policy housing_runs_own on public.housing_match_runs for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy housing_results_own on public.housing_match_results for all to authenticated using (exists (select 1 from public.housing_match_runs r where r.id = run_id and r.user_id = (select auth.uid()))) with check (exists (select 1 from public.housing_match_runs r where r.id = run_id and r.user_id = (select auth.uid())));
create policy housing_saved_own on public.saved_housing_listings for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy broker_profiles_read on public.broker_profiles for select to authenticated using (true);
create policy broker_requests_own on public.broker_match_requests for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy housing_events_own on public.housing_events for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
revoke all on public.housing_preferences,public.housing_listings,public.housing_match_runs,public.housing_match_results,public.saved_housing_listings,public.broker_profiles,public.broker_match_requests,public.housing_events from public,anon,authenticated;
grant select,insert,update,delete on public.housing_preferences,public.housing_match_runs,public.housing_match_results,public.saved_housing_listings,public.broker_match_requests,public.housing_events to authenticated; grant select on public.housing_listings,public.broker_profiles to authenticated; grant all on all tables in schema public to service_role;
commit;
